<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DistroScope - Beginner Kit</title>
    <style>
        :root {
            --bg-color: #0f0518;
            --card-bg: rgba(255, 255, 255, 0.04);
            --card-border: rgba(255, 255, 255, 0.08);
            --text-primary: #ffffff;
            --text-secondary: #a0a0b0;
            --accent-purple: #9333ea;
            --accent-pink: #ec4899;
            --accent-gold: #fbbf24;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --glass-blur: 16px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            background-image: 
                radial-gradient(circle at 15% 50%, rgba(120, 0, 200, 0.25) 0%, transparent 40%),
                radial-gradient(circle at 85% 30%, rgba(80, 0, 150, 0.2) 0%, transparent 45%),
                linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
            background-size: 100% 100%, 100% 100%, 60px 60px, 60px 60px;
            color: var(--text-primary);
            font-family: var(--font-sans);
            line-height: 1.5;
            min-height: 100vh;
            padding-bottom: 4rem;
        }

        /* Navbar */
        nav {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 1rem 2rem;
            background: rgba(20, 10, 30, 0.6);
            backdrop-filter: blur(var(--glass-blur));
            border-bottom: 1px solid var(--card-border);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .nav-left { display: flex; align-items: center; gap: 3rem; }

        .logo {
            font-weight: 700;
            font-size: 1.2rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }
        .logo-icon {
            width: 28px; height: 28px;
            background: linear-gradient(135deg, #d946ef, #9333ea);
            border-radius: 6px;
            display: grid; place-items: center;
            color: white; font-weight: bold; font-size: 14px;
        }
        .logo span { color: white; } .logo span:last-child { color: #e879f9; }

        .nav-links { display: flex; gap: 1.5rem; list-style: none; }
        .nav-links a {
            text-decoration: none;
            color: var(--text-secondary);
            font-size: 0.95rem;
            transition: color 0.2s;
        }
        .nav-links a:hover, .nav-links a.active { color: white; }
        .nav-links a.active { font-weight: 500; }

        .nav-right { display: flex; align-items: center; gap: 1rem; }

        .search-bar {
            background: rgba(0,0,0,0.3);
            border: 1px solid var(--card-border);
            padding: 0.5rem 1rem;
            border-radius: 999px;
            color: var(--text-secondary);
            font-size: 0.85rem;
            width: 220px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
        .kbd-shortcut {
            background: rgba(255,255,255,0.1); 
            padding: 2px 6px; 
            border-radius: 4px; 
            font-size: 0.7rem; 
            margin-left: 8px;
        }

        .btn-primary {
            background: linear-gradient(90deg, #a855f7, #c026d3);
            color: white;
            border: none;
            padding: 0.5rem 1.2rem;
            border-radius: 99px;
            font-weight: 600;
            cursor: pointer;
            display: flex; align-items: center; gap: 6px;
            font-size: 0.9rem;
            box-shadow: 0 4px 12px rgba(168, 85, 247, 0.3);
            transition: transform 0.1s;
        }
        .btn-primary:active { transform: scale(0.98); }

        /* Main Content */
        main {
            max-width: 1280px;
            margin: 0 auto;
            padding: 3rem 2rem;
        }

        /* Header Section */
        header.text-center { text-align: center; margin-bottom: 3rem; position: relative; }

        .section-badge {
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            background: rgba(255,255,255,0.06);
            border: 1px solid var(--card-border);
            padding: 0.4rem 1rem;
            border-radius: 99px;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--text-secondary);
            margin-bottom: 1.5rem;
            backdrop-filter: blur(4px);
        }
        .badge-icon { color: var(--accent-gold); }

        h1 {
            font-size: 2.8rem;
            font-weight: 800;
            letter-spacing: -0.02em;
            margin-bottom: 1rem;
            background: linear-gradient(to right, #fff, #e9d5ff);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }
        h1 span { color: #f472b6; -webkit-text-fill-color: #f472b6; }

        .subtitle {
            max-width: 650px;
            margin: 0 auto 2rem;
            color: var(--text-secondary);
            font-size: 1.05rem;
        }

        .meta-tags {
            display: flex;
            justify-content: center;
            gap: 1rem;
            flex-wrap: wrap;
        }
        .tag {
            display: flex; align-items: center; gap: 6px;
            background: rgba(255,255,255,0.03);
            border: 1px solid rgba(255,255,255,0.06);
            padding: 0.4rem 0.8rem;
            border-radius: 8px;
            font-size: 0.8rem;
            color: var(--text-secondary);
        }
        .tag svg { width: 14px; height: 14px; opacity: 0.8; }

        /* Grid Layout */
        .content-grid {
            display: grid;
            grid-template-columns: 420px 1fr;
            gap: 2rem;
            align-items: start;
        }

        /* Glass Card Style */
        .glass-card {
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 20px;
            padding: 1.5rem;
            backdrop-filter: blur(var(--glass-blur));
            box-shadow: 0 12px 40px rgba(0,0,0,0.2);
        }

        /* Left Column: Timeline */
        .timeline-header {
            margin-bottom: 1.5rem;
        }
        .timeline-header h2 { font-size: 1.25rem; margin-bottom: 0.3rem; }
        .timeline-header p { font-size: 0.85rem; color: var(--text-secondary); }

        .progress-bar-container {
            height: 4px;
            background: rgba(255,255,255,0.1);
            border-radius: 2px;
            margin-bottom: 2rem;
            position: relative;
        }
        .progress-fill {
            position: absolute; left: 0; top: 0; bottom: 0;
            width: 0%; /* Dynamic in JS usually, static here for demo */
            background: linear-gradient(90deg, #fbbf24, #f59e0b);
            border-radius: 2px;
            width: 0%; /* Step 1 active implies some progress or just visual */
        }
        .progress-text {
            display: flex; justify-content: space-between;
            font-size: 0.75rem; color: var(--accent-gold); margin-top: 6px;
            font-weight: 600;
        }

        .step-item {
            display: flex;
            gap: 1.2rem;
            position: relative;
            padding-bottom: 2rem;
        }
        .step-item:not(:last-child)::before {
            content: '';
            position: absolute;
            left: 14px;
            top: 32px;
            bottom: 0;
            width: 2px;
            background: rgba(255,255,255,0.08);
            z-index: 0;
        }
        /* Active line */
        .step-item.active::before {
            background: var(--accent-gold);
            box-shadow: 0 0 8px var(--accent-gold);
        }

        .step-number {
            width: 30px; height: 30px;
            border-radius: 50%;
            background: rgba(255,255,255,0.03);
            border: 1px solid var(--card-border);
            display: flex; align-items: center; justify-content: center;
            font-size: 0.75rem;
            font-weight: 700;
            color: var(--text-secondary);
            flex-shrink: 0;
            z-index: 1;
            position: relative;
        }
        .step-item.active .step-number {
            background: rgba(251, 191, 36, 0.15);
            border-color: var(--accent-gold);
            color: var(--accent-gold);
            box-shadow: 0 0 15px rgba(251, 191, 36, 0.2);
        }

        .step-content { flex: 1; }
        .step-title-row { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 0.4rem; }
        .step-title { font-weight: 600; font-size: 0.95rem; display: flex; align-items: center; gap: 0.5rem; }
        .step-time { font-size: 0.75rem; color: var(--text-secondary); display: flex; align-items: center; gap: 4px;}

        .step-desc { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 0.8rem; line-height: 1.4; }
        .step-code-hint {
            font-family: monospace;
            font-size: 0.75rem;
            background: rgba(0,0,0,0.3);
            padding: 0.3rem 0.6rem;
            border-radius: 6px;
            color: #d8b4fe;
            display: inline-block;
        }

        /* Right Column: Grid */
        .right-header { margin-bottom: 1.5rem; }
        .right-header h2 { font-size: 1.25rem; margin-bottom: 0.3rem; }
        .right-header p { font-size: 0.85rem; color: var(--text-secondary); }

        .apps-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
            gap: 1rem;
            margin-bottom: 2rem;
        }

        .app-card {
            background: rgba(255,255,255,0.02);
            border: 1px solid rgba(255,255,255,0.05);
            border-radius: 12px;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            gap: 0.6rem;
            transition: all 0.2s ease;
            cursor: pointer;
            position: relative;
            overflow: hidden;
        }
        .app-card:hover {
            background: rgba(255,255,255,0.06);
            border-color: rgba(255,255,255,0.15);
            transform: translateY(-2px);
        }
        .app-card::after {
            content: '';
            position: absolute; inset: 0;
            background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.03));
            pointer-events: none;
        }

        .app-top { display: flex; align-items: center; gap: 0.8rem; }
        .app-icon {
            width: 32px; height: 32px;
            border-radius: 8px;
            background: rgba(255,255,255,0.1);
            display: grid; place-items: center;
            color: white;
        }
        .app-info h4 { font-size: 0.9rem; font-weight: 600; }
        .app-info span { font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em;}

        .app-id {
            font-family: monospace;
            font-size: 0.7rem;
            color: rgba(255,255,255,0.4);
            background: rgba(0,0,0,0.2);
            padding: 2px 6px;
            border-radius: 4px;
            align-self: flex-start;
        }

        /* CTA Area */
        .cta-box {
            background: linear-gradient(105deg, rgba(168, 85, 247, 0.1), rgba(236, 72, 153, 0.05));
            border: 1px solid rgba(168, 85, 247, 0.2);
            border-radius: 16px;
            padding: 1.5rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
        .cta-text h3 { font-size: 1.1rem; margin-bottom: 0.3rem; }
        .cta-text p { font-size: 0.85rem; color: var(--text-secondary); }
        .btn-gh {
            background: #21262d;
            color: white;
            border: 1px solid #30363d;
            padding: 0.6rem 1.2rem;
            border-radius: 8px;
            font-weight: 600;
            font-size: 0.9rem;
            display: flex; align-items: center; gap: 8px;
            cursor: pointer;
            transition: background 0.2s;
        }
        .btn-gh:hover { background: #30363d; }

        /* Floating Elements */
        .fab {
            position: fixed;
            bottom: 2rem; right: 2rem;
            width: 48px; height: 48px;
            border-radius: 50%;
            background: rgba(255,255,255,0.1);
            border: 1px solid rgba(255,255,255,0.2);
            display: grid; place-items: center;
            color: white;
            cursor: pointer;
            backdrop-filter: blur(10px);
            z-index: 200;
        }

        /* Icons (SVG) */
        .icon { width: 1em; height: 1em; fill: currentColor; }
    </style>
</head>
